const http = require('http');
const WebSocket = require('ws');
const { setupWSConnection } = require('y-websocket/bin/utils');
const { parseSession } = require('./auth');
const { canAccessDocument } = require('./permissions');

const server = http.createServer();
const wss = new WebSocket.Server({ noServer: true });

server.on('upgrade', async (request, socket, head) => {
  const user = parseSession(request);
  if (!user) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  const docName = request.url.slice(1).split('?')[0];

  // Verify that authenticated user has read/write rights on the collaborative document
  const allowed = await canAccessDocument(user.id, docName);
  if (!allowed) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    setupWSConnection(ws, request, { docName });
  });
});

module.exports = server;
